"use client";

import { useState } from "react";
import Link from "next/link";
import { AlertTriangle, ChevronLeft, ChevronRight, CircleCheck, Info, LockKeyhole, Plus, ShieldAlert, Trash2 } from "lucide-react";
import { BreadcrumbLabel } from "@/components/app-shell/breadcrumb-label";
import { BankStatementImportAction } from "@/components/reports/bank-statement-import-action";
import { PageHeader, StatusBadge, useToast } from "@/components/design-system";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { WorkflowActionDialog, type WorkflowActionResult } from "@/components/workflows/workflow-action-dialog";
import { buildQuarterlyCashFlowSubtitle, dbeQuarterlyCashFlowSections, quarterlyCashFlowTotals, subtractGrantAmounts, sumGrantAmounts, type DbeQuarterlyCashFlowSectionId } from "@/lib/grant-reports/editor";
import { applyQuarterlyReportingPeriod } from "@/lib/grant-reports/quarterly-period";
import { grantReadinessPresentation } from "@/lib/grant-reports/presentation";
import { canShowQuarterlySubmissionAction, selectSubmissionAcknowledgementWarnings, type SubmissionCheckGroup } from "@/lib/grant-reports/submission-readiness";
import { formatGrantCurrency, formatGrantLabel, formatGrantReconciliationCurrency, reportTypeLabels, type GrantReportEditorData } from "@/lib/grant-reports/types";

const inputClass = "mt-1 w-full rounded-lg border border-brand-line bg-white px-3 py-2 text-sm text-brand-ink outline-none focus:border-brand-navy disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500 dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:disabled:bg-slate-800";
const compactInputClass = "w-full min-w-24 rounded-md border border-brand-line bg-white px-2 py-1.5 text-sm text-brand-ink outline-none focus:border-brand-navy disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500 dark:border-slate-700 dark:bg-slate-950 dark:text-white dark:disabled:bg-slate-800";
type CashDraft = { id?: string; lineType: "FUNDING_RECEIVED" | "OTHER_INCOME"; categoryName: string; amount: string };
type ExpenseDraft = { id?: string; categoryName: string; quarterlyBudget: string; estimatedExpenditure: string; variance: string; reasonForVariance: string };
type CertificationDraft = { party: "COMPILER" | "APPROVER"; nameSnapshot: string; designationSnapshot: string; certificationDate: string; digitallyConfirmed: boolean };

function dateInput(value: string | null) { return value?.slice(0, 10) ?? ""; }
function displayDate(value: string | null) { return value ? new Intl.DateTimeFormat("en-ZA", { dateStyle: "medium" }).format(new Date(value)) : "Not provided"; }
function money(value: string | null) { return value ?? ""; }
function moneyLabel(value: string | null, currency: string) { return formatGrantCurrency(Number(value ?? 0), currency); }
function varianceFor(row: Pick<ExpenseDraft, "quarterlyBudget" | "estimatedExpenditure">) { return subtractGrantAmounts(row.quarterlyBudget || "0.00", row.estimatedExpenditure || "0.00") ?? "0.00"; }

export function DbeQuarterlyCashFlowEditor({ initialData }: { initialData: GrantReportEditorData }) {
  const { pushToast } = useToast();
  const [data, setData] = useState(initialData);
  const [activeSection, setActiveSection] = useState<DbeQuarterlyCashFlowSectionId>("cash_flow_general");
  const [saving, setSaving] = useState<DbeQuarterlyCashFlowSectionId | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [general, setGeneral] = useState(() => applyQuarterlyReportingPeriod({ financialYear: initialData.general.financialYear ?? "", quarter: initialData.general.quarter ? String(initialData.general.quarter) : "", reportingPeriodStart: dateInput(initialData.general.reportingPeriodStart), reportingPeriodEnd: dateInput(initialData.general.reportingPeriodEnd) }));
  const [cashRows, setCashRows] = useState<CashDraft[]>(() => initialData.quarterlyCashFlow.cashReceivedRows.map((row) => ({ ...row, amount: money(row.amount) })));
  const [expenseRows, setExpenseRows] = useState<ExpenseDraft[]>(() => initialData.quarterlyCashFlow.operatingExpenseRows.map((row) => ({ ...row, quarterlyBudget: money(row.quarterlyBudget), estimatedExpenditure: money(row.estimatedExpenditure), variance: row.variance, reasonForVariance: row.reasonForVariance ?? "" })));
  const [certifications, setCertifications] = useState<CertificationDraft[]>(() => (["COMPILER", "APPROVER"] as const).map((party) => { const existing = initialData.certifications.find((row) => row.party === party); return { party, nameSnapshot: existing?.nameSnapshot ?? "", designationSnapshot: existing?.designationSnapshot ?? "", certificationDate: dateInput(existing?.certificationDate ?? null), digitallyConfirmed: existing?.digitallyConfirmed ?? false }; }));
  const editable = data.version.editable;
  const currentIndex = dbeQuarterlyCashFlowSections.findIndex((section) => section.id === activeSection);
  const totalCashAvailable = sumGrantAmounts(cashRows.map((row) => row.amount || null)) ?? "0.00";
  const totals = quarterlyCashFlowTotals(cashRows.map((row) => row.amount || null), expenseRows.map((row) => ({ quarterlyBudget: row.quarterlyBudget || null, estimatedExpenditure: row.estimatedExpenditure || null })));

  async function saveSection(section: "cash_flow_general" | "cash_received" | "operating_expenses" | "certification", payload: unknown) {
    if (!editable || saving) return;
    setSaving(activeSection); setError(null);
    try {
      const response = await fetch(`/api/grant-reports/${data.report.id}/sections`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ section, data: payload }) });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error ?? "The report section could not be saved.");
      setData(body.data); pushToast({ title: "Draft saved", description: `${dbeQuarterlyCashFlowSections.find((item) => item.id === activeSection)?.label} was saved.` });
    } catch (caught) { const message = caught instanceof Error ? caught.message : "The report section could not be saved."; setError(message); pushToast({ title: "Save failed", description: message }); }
    finally { setSaving(null); }
  }

  function expensePayload() { return { rows: expenseRows.map((row) => ({ ...row, quarterlyBudget: row.quarterlyBudget || null, estimatedExpenditure: row.estimatedExpenditure || null, variance: varianceFor(row), reasonForVariance: row.reasonForVariance.trim() || null })), totalCashAvailable, totalQuarterlyBudget: totals.totalQuarterlyBudget ?? "0.00", totalExpenditure: totals.totalExpenditure ?? "0.00", totalVariance: totals.totalVariance ?? "0.00", remainingCash: totals.remainingCash ?? "0.00" }; }
  function saveActiveSection() {
    if (activeSection === "cash_flow_general") return saveSection("cash_flow_general", general);
    if (activeSection === "cash_received") return saveSection("cash_received", { rows: cashRows.map((row) => ({ ...row, amount: row.amount || null })), totalCashAvailable });
    if (activeSection === "operating_expenses" || activeSection === "variance_review") return saveSection("operating_expenses", expensePayload());
    if (activeSection === "financial_reconciliation" || activeSection === "submission_readiness") return;
    return saveSection("certification", { rows: certifications.map((row) => ({ ...row, certificationDate: row.certificationDate || null })) });
  }

  if (data.version.submittedAt) return <SubmittedCashFlowReview data={data} />;
  const subtitle = buildQuarterlyCashFlowSubtitle({ reportTitle: data.report.title, centreName: data.general.centreName, leadOrganisation: data.general.leadOrganisation, financialYear: general.financialYear || null, quarter: general.quarter ? Number(general.quarter) : null });
  return <div className="space-y-6 pb-10">
    <BreadcrumbLabel label="Quarterly Cash Flow Report" />
    <PageHeader eyebrow="Super Admin · Grant Reports" title="Quarterly Cash Flow Report" description={subtitle} actions={<div className="flex flex-wrap gap-2">{editable ? <BankStatementImportAction reportId={data.report.id} /> : null}<Link href="/dashboard/super-admin/reports"><Button variant="secondary"><ChevronLeft className="h-4 w-4" />All Reports</Button></Link></div>} />
    {data.version.status === "SUBMITTED" ? <div className="rounded-lg border border-green-200 bg-green-50 p-4 text-sm text-green-900"><p className="font-bold">Submitted</p><p className="mt-1">Submitted {data.version.submittedAt ? `on ${displayDate(data.version.submittedAt)}` : ""}{data.version.submittedBy ? ` by ${data.version.submittedBy}` : ""}. Submitted reports are read-only.</p></div> : null}
    <Card className="dark:border-slate-800 dark:bg-slate-900"><CardContent className="grid gap-5 p-5 lg:grid-cols-[1fr_auto] lg:items-center"><div className="flex flex-wrap items-center gap-3"><Badge>{reportTypeLabels[data.report.type]}</Badge><StatusBadge status={formatGrantLabel(data.version.status)} /><span className="text-sm text-slate-500">Version {data.version.versionNumber}</span><span className="text-sm text-slate-500">Reporting period: {displayDate(data.general.reportingPeriodStart)} – {displayDate(data.general.reportingPeriodEnd)}</span>{!editable ? <span className="inline-flex items-center gap-1 text-sm font-bold text-slate-600"><LockKeyhole className="h-4 w-4" />Read-only report version</span> : null}</div><div className="min-w-52"><div className="mb-2 flex justify-between text-xs font-bold"><span>{editable ? "Draft completeness" : "Report completeness"}</span><span>{data.version.completion.percentage}%</span></div><Progress value={data.version.completion.percentage} /><p className="mt-2 text-xs text-slate-500">{data.version.status === "SUBMITTED" ? "Official submitted version" : data.version.completion.readyForSubmission ? "Ready for submission" : "Incomplete draft"}</p></div></CardContent></Card>
    <div className="grid gap-6 lg:grid-cols-[250px_minmax(0,1fr)]"><nav aria-label="Report sections" className="h-fit space-y-1 rounded-lg border border-brand-line bg-white p-2 lg:sticky lg:top-4 dark:border-slate-800 dark:bg-slate-900">{dbeQuarterlyCashFlowSections.map((section, index) => <button key={section.id} type="button" onClick={() => { setActiveSection(section.id); setError(null); }} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-bold ${activeSection === section.id ? "bg-brand-navy text-white" : "text-slate-600 hover:bg-brand-accent dark:text-slate-300"}`}><span className={`flex h-6 w-6 items-center justify-center rounded-full text-xs ${activeSection === section.id ? "bg-white/20" : "bg-slate-100 dark:bg-slate-800"}`}>{index + 1}</span>{section.label}</button>)}</nav>
      <main className="min-w-0 space-y-4">{activeSection === "cash_flow_general" ? <CashFlowGeneral data={data} value={general} setValue={setGeneral} editable={editable} /> : null}{activeSection === "cash_received" ? <CashReceived data={data} rows={cashRows} setRows={setCashRows} total={totalCashAvailable} editable={editable} /> : null}{activeSection === "operating_expenses" ? <OperatingExpenses rows={expenseRows} setRows={setExpenseRows} totals={totals} currency={data.version.currency} editable={editable} /> : null}{activeSection === "variance_review" ? <VarianceReview rows={expenseRows} setRows={setExpenseRows} currency={data.version.currency} editable={editable} /> : null}{activeSection === "financial_reconciliation" ? <FinancialReconciliation data={data} /> : null}{activeSection === "submission_readiness" ? <SubmissionReadiness data={data} onNavigate={setActiveSection} /> : null}{activeSection === "certification" ? <CashFlowCertification data={data} rows={certifications} setRows={setCertifications} editable={editable} onNavigate={setActiveSection} onSubmitted={setData} /> : null}{error ? <p className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm font-semibold text-red-700">{error}</p> : null}<div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-brand-line bg-white p-4 dark:border-slate-800 dark:bg-slate-900"><Button type="button" variant="secondary" disabled={currentIndex === 0} onClick={() => setActiveSection(dbeQuarterlyCashFlowSections[currentIndex - 1].id)}><ChevronLeft className="h-4 w-4" />Previous</Button><div className="flex gap-3">{activeSection !== "financial_reconciliation" && activeSection !== "submission_readiness" ? <Button type="button" disabled={!editable || Boolean(saving)} onClick={() => void saveActiveSection()}>{saving === activeSection ? "Saving…" : "Save Draft"}</Button> : <span className="self-center text-xs font-semibold text-slate-500">Read-only review</span>}<Button type="button" variant="secondary" disabled={currentIndex === dbeQuarterlyCashFlowSections.length - 1} onClick={() => setActiveSection(dbeQuarterlyCashFlowSections[currentIndex + 1].id)}>Next<ChevronRight className="h-4 w-4" /></Button></div></div></main>
    </div>
  </div>;
}

function SubmittedCashFlowReview({ data }: { data: GrantReportEditorData }) {
  const [activeSection, setActiveSection] = useState<DbeQuarterlyCashFlowSectionId>("cash_flow_general");
  const currentIndex = dbeQuarterlyCashFlowSections.findIndex((section) => section.id === activeSection);
  const currency = data.version.currency;
  const exact = (amount: string | null) => amount === null ? "Not recorded" : formatGrantReconciliationCurrency(amount, currency);
  const cashRows = data.quarterlyCashFlow.cashReceivedRows.map((row, index) => ({ ...row, id: `cash-${index}` }));
  const expenseRows = data.quarterlyCashFlow.operatingExpenseRows.map((row, index) => ({ ...row, id: `expense-${index}` }));
  const variedRows = expenseRows.filter((row) => row.variance !== "0.00");
  const subtitle = buildQuarterlyCashFlowSubtitle({ reportTitle: data.report.title, centreName: data.general.centreName, leadOrganisation: data.general.leadOrganisation, financialYear: data.general.financialYear, quarter: data.general.quarter });

  return <div className="space-y-6 pb-10" data-submitted-cash-flow-review>
    <BreadcrumbLabel label="Quarterly Cash Flow Report" />
    <PageHeader eyebrow="Super Admin · Grant Reports" title="Quarterly Cash Flow Report" description={subtitle} actions={<Link href="/dashboard/super-admin/reports"><Button variant="secondary"><ChevronLeft className="h-4 w-4" />All Reports</Button></Link>} />
    <div className="rounded-lg border border-green-200 bg-green-50 p-4 text-sm text-green-900"><p className="font-bold">Submitted</p><p className="mt-1">Submitted {displayDate(data.version.submittedAt)}{data.version.submittedBy ? ` by ${data.version.submittedBy}` : ""}. Submitted reports are read-only.</p></div>
    <Card className="dark:border-slate-800 dark:bg-slate-900"><CardContent className="grid gap-5 p-5 lg:grid-cols-[1fr_auto] lg:items-center"><div className="flex flex-wrap items-center gap-3"><Badge>{reportTypeLabels[data.report.type]}</Badge><StatusBadge status={formatGrantLabel(data.version.status)} /><span className="text-sm text-slate-500">Version {data.version.versionNumber}</span><span className="text-sm text-slate-500">Reporting period: {displayDate(data.general.reportingPeriodStart)} – {displayDate(data.general.reportingPeriodEnd)}</span><span className="inline-flex items-center gap-1 text-sm font-bold text-slate-600"><LockKeyhole className="h-4 w-4" />Read-only report version</span></div><div className="min-w-52"><div className="mb-2 flex justify-between text-xs font-bold"><span>Report completeness</span><span>{data.version.completion.percentage}%</span></div><Progress value={data.version.completion.percentage} /><p className="mt-2 text-xs text-slate-500">Official submitted version</p></div></CardContent></Card>
    <div className="grid gap-6 lg:grid-cols-[250px_minmax(0,1fr)]">
      <nav aria-label="Report sections" className="h-fit space-y-1 rounded-lg border border-brand-line bg-white p-2 lg:sticky lg:top-4 dark:border-slate-800 dark:bg-slate-900">{dbeQuarterlyCashFlowSections.map((section, index) => <button key={section.id} type="button" onClick={() => setActiveSection(section.id)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-bold ${activeSection === section.id ? "bg-brand-navy text-white" : "text-slate-600 hover:bg-brand-accent dark:text-slate-300"}`}><span className={`flex h-6 w-6 items-center justify-center rounded-full text-xs ${activeSection === section.id ? "bg-white/20" : "bg-slate-100 dark:bg-slate-800"}`}>{index + 1}</span>{section.label}</button>)}</nav>
      <main className="min-w-0 space-y-4">
        {activeSection === "cash_flow_general" ? <SectionCard title="General Information" description="Saved centre, award and reporting-period details for this submitted version."><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Field label="Organisation / Centre Name" value={data.general.centreName} /><Field label="NPO Number" value={data.general.npoNumber} /><Field label="Physical Address" value={data.general.physicalAddress} /><Field label="Contact Person" value={data.general.contactPerson} /><Field label="Telephone" value={data.general.telephone} /><Field label="Email" value={data.general.email} /><Field label="Funding Organisation" value={data.general.leadOrganisation} /><Field label="Financial Year" value={data.general.financialYear} /><Field label="Quarter" value={data.general.quarter ? `Quarter ${data.general.quarter}` : null} /><Field label="Reporting Period Start" value={displayDate(data.general.reportingPeriodStart)} /><Field label="Reporting Period End" value={displayDate(data.general.reportingPeriodEnd)} /></div></SectionCard> : null}
        {activeSection === "cash_received" ? <SectionCard title="Cash Received" description="Saved cash received lines for this reporting quarter."><div className="overflow-x-auto"><table className="w-full min-w-[580px] text-sm"><thead><tr className="border-b text-left"><th className="p-2">Cash Received Type</th><th className="p-2">Source / Description</th><th className="p-2 text-right">Amount</th></tr></thead><tbody>{cashRows.map((row, index) => <tr key={row.id ?? `cash-${index}`} className="border-b border-brand-line"><td className="p-2">{row.lineType === "FUNDING_RECEIVED" ? "Subsidy" : "Other Income"}</td><td className="p-2">{row.categoryName}</td><td className="p-2 text-right font-semibold tabular-nums">{exact(row.amount)}</td></tr>)}</tbody><tfoot><tr className="bg-slate-50 font-bold dark:bg-slate-800"><td className="p-3" colSpan={2}>Total Cash Available</td><td className="p-3 text-right tabular-nums">{exact(data.quarterlyCashFlow.totals.totalCashAvailable)}</td></tr></tfoot></table></div></SectionCard> : null}
        {activeSection === "operating_expenses" ? <div className="space-y-4"><SectionCard title="Operating Expenses" description="Saved quarterly expense and variance lines."><div className="overflow-x-auto"><table className="w-full min-w-[820px] text-sm"><thead><tr className="border-b text-left"><th className="p-2">Expense / Cost Item</th><th className="p-2 text-right">Quarterly Budget</th><th className="p-2 text-right">Expenditure</th><th className="p-2 text-right">Variance</th><th className="p-2">Reason for Under / Over Spending</th></tr></thead><tbody>{expenseRows.map((row, index) => <tr key={row.id ?? `expense-${index}`} className="border-b border-brand-line"><td className="p-2">{row.categoryName}</td><td className="p-2 text-right tabular-nums">{exact(row.quarterlyBudget)}</td><td className="p-2 text-right tabular-nums">{exact(row.estimatedExpenditure)}</td><td className="p-2 text-right tabular-nums">{exact(row.variance)}</td><td className="p-2">{row.reasonForVariance || "—"}</td></tr>)}</tbody></table></div></SectionCard><SectionCard title="Quarterly Cash Summary"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Field label="Total Cash Available" value={exact(data.quarterlyCashFlow.totals.totalCashAvailable)} /><Field label="Total Quarterly Budget Allocation" value={exact(data.quarterlyCashFlow.totals.totalQuarterlyBudget)} /><Field label="Total Estimated / Actual Expenditure" value={exact(data.quarterlyCashFlow.totals.totalExpenditure)} /><Field label="Total Variance" value={exact(data.quarterlyCashFlow.totals.totalVariance)} /><Field label="Remaining Cash" value={exact(data.quarterlyCashFlow.totals.remainingCash)} /></div></SectionCard></div> : null}
        {activeSection === "variance_review" ? <SectionCard title="Variance & Reasons" description="Saved reasons for under- and over-spending.">{variedRows.length ? <div className="space-y-3">{variedRows.map((row, index) => <div key={row.id ?? `variance-${index}`} className="grid gap-3 rounded-lg border border-brand-line p-4 sm:grid-cols-2 xl:grid-cols-5"><Field label="Expense Item" value={row.categoryName} /><Field label="Budget" value={exact(row.quarterlyBudget)} /><Field label="Expenditure" value={exact(row.estimatedExpenditure)} /><Field label="Variance" value={exact(row.variance)} /><Field label="Reason for Under / Over Spending" value={row.reasonForVariance} /></div>)}</div> : <p className="text-sm text-slate-500">No under- or over-spending has been recorded for this quarter.</p>}</SectionCard> : null}
        {activeSection === "financial_reconciliation" ? <FinancialReconciliation data={data} /> : null}
        {activeSection === "submission_readiness" ? <SubmissionReadiness data={data} onNavigate={setActiveSection} /> : null}
        {activeSection === "certification" ? <SectionCard title="Certification & Review" description="Recorded compiler and approver certifications for the submitted version."><div className="space-y-3">{data.certifications.map((row) => <div key={row.id} className="rounded-lg border border-brand-line p-4"><h3 className="font-bold">{row.party === "COMPILER" ? "Compiled By" : "Approved / Authorised By"}</h3><div className="mt-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><Field label="Name" value={row.nameSnapshot} /><Field label="Designation" value={row.designationSnapshot} /><Field label="Certification Date" value={displayDate(row.certificationDate)} /></div><p className="mt-2 text-xs text-slate-500">{row.digitallyConfirmed ? `Digitally confirmed ${displayDate(row.confirmedAt)} by ${row.confirmedBy ?? "Internal user"}` : "Not digitally confirmed"}</p></div>)}</div><FinalSubmission data={data} onNavigate={setActiveSection} onSubmitted={() => {}} /></SectionCard> : null}
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-brand-line bg-white p-4 dark:border-slate-800 dark:bg-slate-900">{currentIndex > 0 ? <Button type="button" variant="secondary" onClick={() => setActiveSection(dbeQuarterlyCashFlowSections[currentIndex - 1].id)}><ChevronLeft className="h-4 w-4" />Previous</Button> : <span /> }<span className="text-xs font-semibold text-slate-500">Read-only review</span>{currentIndex < dbeQuarterlyCashFlowSections.length - 1 ? <Button type="button" variant="secondary" onClick={() => setActiveSection(dbeQuarterlyCashFlowSections[currentIndex + 1].id)}>Next<ChevronRight className="h-4 w-4" /></Button> : <span />}</div>
      </main>
    </div>
  </div>;
}

function CashFlowGeneral({ data, value, setValue, editable }: { data: GrantReportEditorData; value: { financialYear: string; quarter: string; reportingPeriodStart: string; reportingPeriodEnd: string }; setValue: React.Dispatch<React.SetStateAction<typeof value>>; editable: boolean }) { return <SectionCard title="General Information" description="Centre, award and funding details already held by ECDLink are shown automatically."><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><Field label="Organisation / Centre Name" value={data.general.centreName} /><Field label="NPO Number" value={data.general.npoNumber} /><Field label="Physical Address" value={data.general.physicalAddress} /><Field label="Contact Person" value={data.general.contactPerson} /><Field label="Telephone" value={data.general.telephone} /><Field label="Email" value={data.general.email} /><Field label="Funding Organisation" value={data.general.leadOrganisation} /><Field label="Due Date" value={displayDate(data.report.dueAt)} /></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><label className="text-sm font-bold">Financial Year<input className={inputClass} value={value.financialYear} disabled={!editable} onChange={(event) => setValue((current) => applyQuarterlyReportingPeriod({ ...current, financialYear: event.target.value }))} /></label><label className="text-sm font-bold">Quarter<select className={inputClass} value={value.quarter} disabled={!editable} onChange={(event) => setValue((current) => applyQuarterlyReportingPeriod({ ...current, quarter: event.target.value }))}><option value="">Select quarter</option>{[1,2,3,4].map((quarter) => <option key={quarter} value={quarter}>Quarter {quarter}</option>)}</select></label><label className="text-sm font-bold">Reporting Period Start<input className={inputClass} type="date" value={value.reportingPeriodStart} disabled={!editable} readOnly /></label><label className="text-sm font-bold">Reporting Period End<input className={inputClass} type="date" value={value.reportingPeriodEnd} disabled={!editable} readOnly /></label></div></SectionCard>; }

function CashReceived({ data, rows, setRows, total, editable }: { data: GrantReportEditorData; rows: CashDraft[]; setRows: React.Dispatch<React.SetStateAction<CashDraft[]>>; total: string; editable: boolean }) { return <SectionCard title="Cash Received" description="Record the cash available for this reporting quarter.">{!data.quarterlyCashFlow.cashReceivedSaved && data.quarterlyCashFlow.matchingExpenditureIncomeFound ? <p className="rounded-lg bg-blue-50 p-3 text-sm text-brand-navy">Cash received was pre-filled from the matching saved Quarterly Expenditure report. Review the amounts before saving.</p> : null}{!data.quarterlyCashFlow.cashReceivedSaved && !data.quarterlyCashFlow.matchingExpenditureIncomeFound ? <p className="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">No matching Quarterly Expenditure income was found for this quarter. Enter cash received below.</p> : null}<div className="overflow-x-auto"><table className="w-full min-w-[760px] table-fixed text-sm"><colgroup><col className="w-[24%]" /><col className="w-[46%]" /><col className="w-[18%]" /><col className="w-[12%]" /></colgroup><thead><tr className="border-b text-left"><th className="p-2">Cash Received Type</th><th className="p-2">Source / Description</th><th className="p-2">Amount</th><th className="p-2">Action</th></tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? `cash-${index}`} className="border-b border-brand-line"><td className="p-2"><select aria-label={`Cash received type ${index + 1}`} className={compactInputClass} value={row.lineType} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, lineType: event.target.value as CashDraft["lineType"] } : item))}><option value="FUNDING_RECEIVED">Subsidy</option><option value="OTHER_INCOME">Other Income</option></select></td><td className="p-2"><input aria-label={`Cash source ${index + 1}`} className={compactInputClass} value={row.categoryName} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, categoryName: event.target.value } : item))} /></td><td className="p-2"><input aria-label={`Cash amount ${index + 1}`} className={compactInputClass} inputMode="decimal" placeholder="0.00" value={row.amount} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, amount: event.target.value } : item))} /></td><td className="p-2"><Button type="button" variant="ghost" disabled={!editable || rows.length === 1} onClick={() => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index))}><Trash2 className="h-4 w-4" />Remove</Button></td></tr>)}</tbody><tfoot><tr className="bg-slate-50 font-bold dark:bg-slate-800"><td className="p-3" colSpan={2}>Total Cash Available</td><td className="p-3">{moneyLabel(total, data.version.currency)}</td><td /></tr></tfoot></table></div><Button type="button" variant="secondary" disabled={!editable} onClick={() => setRows((current) => [...current, { lineType: "OTHER_INCOME", categoryName: "Additional Cash Received", amount: "" }])}><Plus className="h-4 w-4" />Add cash received line</Button></SectionCard>; }

function OperatingExpenses({ rows, setRows, totals, currency, editable }: { rows: ExpenseDraft[]; setRows: React.Dispatch<React.SetStateAction<ExpenseDraft[]>>; totals: ReturnType<typeof quarterlyCashFlowTotals>; currency: string; editable: boolean }) { const update = (index: number, field: keyof ExpenseDraft, value: string) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, [field]: value, variance: field === "quarterlyBudget" ? subtractGrantAmounts(value || "0.00", row.estimatedExpenditure || "0.00") ?? "0.00" : field === "estimatedExpenditure" ? subtractGrantAmounts(row.quarterlyBudget || "0.00", value || "0.00") ?? "0.00" : row.variance } : row)); return <div className="space-y-6"><SectionCard title="Operating Expenses" description="Record the quarterly budget and estimated or actual expenditure for each operating cost."><div className="overflow-x-auto"><table className="w-full min-w-[820px] table-fixed text-xs"><colgroup><col className="w-[24%]" /><col className="w-[17%]" /><col className="w-[19%]" /><col className="w-[14%]" /><col className="w-[21%]" /><col className="w-[5%]" /></colgroup><thead><tr className="border-b text-left"><th className="p-2">Expense / Cost Item</th><th className="p-2">Quarterly Budget<br />Allocation</th><th className="p-2">Quarterly Estimated /<br />Actual Expenditure</th><th className="p-2">Variance for<br />the Quarter</th><th className="p-2">Reason for Under /<br />Over Spending</th><th className="p-2">Action</th></tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? `expense-${index}`} className="border-b border-brand-line"><td className="p-1.5"><input aria-label={`Expense item ${index + 1}`} className={compactInputClass} value={row.categoryName} disabled={!editable} onChange={(event) => update(index, "categoryName", event.target.value)} /></td><td className="p-1.5"><input aria-label={`Quarterly budget ${index + 1}`} className={compactInputClass} inputMode="decimal" placeholder="0.00" value={row.quarterlyBudget} disabled={!editable} onChange={(event) => update(index, "quarterlyBudget", event.target.value)} /></td><td className="p-1.5"><input aria-label={`Estimated or actual expenditure ${index + 1}`} className={compactInputClass} inputMode="decimal" placeholder="0.00" value={row.estimatedExpenditure} disabled={!editable} onChange={(event) => update(index, "estimatedExpenditure", event.target.value)} /></td><td className="p-1.5"><output aria-label={`Calculated variance ${index + 1}`} className="block whitespace-nowrap rounded-md bg-slate-100 px-2 py-2 text-right font-bold tabular-nums text-brand-ink dark:bg-slate-800 dark:text-white">{moneyLabel(varianceFor(row), currency)}</output></td><td className="p-1.5"><input aria-label={`Variance reason ${index + 1}`} className={compactInputClass} value={row.reasonForVariance} disabled={!editable} onChange={(event) => update(index, "reasonForVariance", event.target.value)} /></td><td className="p-1.5"><button type="button" aria-label={`Remove ${row.categoryName}`} disabled={!editable || rows.length === 1} className="rounded-md p-2 text-slate-500 hover:bg-slate-100 disabled:opacity-50" onClick={() => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index))}><Trash2 className="h-4 w-4" /></button></td></tr>)}</tbody></table></div><Button type="button" variant="secondary" disabled={!editable} onClick={() => setRows((current) => [...current, { categoryName: "Additional Expense", quarterlyBudget: "", estimatedExpenditure: "", variance: "0.00", reasonForVariance: "" }])}><Plus className="h-4 w-4" />Add expense line</Button></SectionCard><CashSummary totals={totals} currency={currency} /></div>; }

function VarianceReview({ rows, setRows, currency, editable }: { rows: ExpenseDraft[]; setRows: React.Dispatch<React.SetStateAction<ExpenseDraft[]>>; currency: string; editable: boolean }) { const varied = rows.map((row, index) => ({ row, index, variance: varianceFor(row) })).filter((item) => item.variance !== "0.00"); return <SectionCard title="Variance & Reasons" description="Review all under- and over-spending recorded for this quarter.">{varied.length ? <div className="space-y-3">{varied.map(({ row, index, variance }) => <div key={row.id ?? `variance-${index}`} className="grid gap-3 rounded-lg border border-brand-line p-4 md:grid-cols-[1.2fr_repeat(3,0.7fr)_1.5fr] md:items-center"><div><p className="text-xs font-bold uppercase text-slate-500">Expense Item</p><p className="font-bold">{row.categoryName}</p></div><Field label="Budget" value={moneyLabel(row.quarterlyBudget, currency)} /><Field label="Expenditure" value={moneyLabel(row.estimatedExpenditure, currency)} /><Field label="Variance" value={moneyLabel(variance, currency)} /><label className="text-sm font-bold">Reason for Under / Over Spending<input className={inputClass} value={row.reasonForVariance} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, reasonForVariance: event.target.value } : item))} /></label></div>)}</div> : <p className="rounded-lg border border-dashed border-brand-line p-8 text-center text-sm text-slate-500">No under- or over-spending has been recorded for this quarter.</p>}</SectionCard>; }

function CashSummary({ totals, currency }: { totals: ReturnType<typeof quarterlyCashFlowTotals>; currency: string }) { return <SectionCard title="Quarterly Cash Summary"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Field label="Total Cash Available" value={moneyLabel(totals.totalCashAvailable, currency)} /><Field label="Total Quarterly Budget Allocation" value={moneyLabel(totals.totalQuarterlyBudget, currency)} /><Field label="Total Estimated / Actual Expenditure" value={moneyLabel(totals.totalExpenditure, currency)} /><Field label="Total Variance" value={moneyLabel(totals.totalVariance, currency)} /><div className={`rounded-lg p-3 ${totals.remainingCash?.startsWith("-") ? "bg-red-50 text-red-800" : "bg-green-50 text-green-800"}`}><p className="text-xs font-bold uppercase tracking-wide">Remaining Cash</p><p className="mt-1 text-lg font-bold">{moneyLabel(totals.remainingCash, currency)}</p></div></div></SectionCard>; }

function FinancialReconciliation({ data }: { data: GrantReportEditorData }) {
  const reconciliation = data.quarterlyCashFlow.financialReconciliation;
  if (!reconciliation) return <SectionCard title="Financial Reconciliation"><p className="rounded-lg border border-dashed border-brand-line p-8 text-center text-sm text-slate-500">Financial reconciliation is available for Quarterly Cash Flow reports.</p></SectionCard>;
  const moneyLabel = (value: string | null, currency: string) => formatGrantReconciliationCurrency(value ?? "0", currency);
  const readinessVariant = reconciliation.readiness === "READY" ? "success" : reconciliation.readiness === "NEEDS_REVIEW" ? "warning" : "muted";
  return <div className="space-y-5">
    <SectionCard title="Financial Reconciliation" description="Review report totals, budget performance and the bank evidence supporting this draft. This review does not change or submit the report.">
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-brand-line bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800"><div><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Financial Readiness</p><p className="mt-1 text-sm text-slate-600 dark:text-slate-300">A review aid based on the current report lines and their evidence.</p></div><Badge variant={readinessVariant}>{formatGrantLabel(reconciliation.readiness)}</Badge></div>
      <div className="grid grid-cols-[repeat(auto-fit,minmax(min(100%,280px),1fr))] gap-4">
        <ReconciliationGroup title="Cash / Funding" rows={[["Opening cash balance", reconciliation.cash.openingCashBalance], ["Funding / grant received", reconciliation.cash.fundingReceived], ["Other income", reconciliation.cash.otherIncome], ["Total Cash Received", reconciliation.cash.totalCashReceived], ["Total Cash Available", reconciliation.cash.totalCashAvailable]]} currency={data.version.currency} />
        <ReconciliationGroup title="Expenditure" rows={[["Quarterly Budget", reconciliation.expenditure.quarterlyBudget], ["Actual Expenditure", reconciliation.expenditure.actualExpenditure], ["Remaining Budget", reconciliation.expenditure.remainingBudget], ["Budget Variance", reconciliation.expenditure.budgetVariance]]} currency={data.version.currency} />
        <ReconciliationGroup title="Bank-derived Position" rows={[["Confirmed bank credits", reconciliation.bankPosition.confirmedCredits], ["Confirmed bank debits", reconciliation.bankPosition.confirmedDebits], ["Net posted bank movement", reconciliation.bankPosition.netMovement]]} currency={data.version.currency} />
        <div className="rounded-lg border border-brand-line p-4 dark:border-slate-700"><h3 className="font-bold">Source Coverage</h3><dl className="mt-3 space-y-2 text-sm"><Metric label="Bank-sourced financial lines" value={String(reconciliation.coverage.bankSourcedFinancialLines)} /><Metric label="Supporting bank transactions" value={String(reconciliation.coverage.supportingBankTransactions)} /><Metric label="Manual financial lines" value={String(reconciliation.coverage.manualFinancialLines)} /><Metric label="Bank-supported amount" value={moneyLabel(reconciliation.coverage.bankSupportedAmount, data.version.currency)} /><Metric label="Manual amount" value={moneyLabel(reconciliation.coverage.manualAmount, data.version.currency)} /><Metric label="Lines without bank evidence" value={String(reconciliation.coverage.linesWithoutBankEvidence)} /></dl></div>
      </div>
    </SectionCard>
    <SectionCard title="Reconciliation Notices" description="Notices identify review items without changing the source data.">{reconciliation.warnings.length ? <div className="space-y-2">{reconciliation.warnings.map((warning, index) => <div key={`${warning.code}-${index}`} className={`flex gap-3 rounded-lg border p-3 text-sm ${warning.severity === "BLOCKING" ? "border-red-200 bg-red-50 text-red-800" : warning.severity === "WARNING" ? "border-amber-200 bg-amber-50 text-amber-800" : "border-blue-200 bg-blue-50 text-brand-navy"}`}>{warning.severity === "BLOCKING" ? <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0" /> : warning.severity === "WARNING" ? <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" /> : <Info className="mt-0.5 h-4 w-4 shrink-0" />}<div><p className="font-bold">{formatGrantLabel(warning.severity)}</p><p>{warning.message}</p></div></div>)}</div> : <div className="flex items-center gap-2 rounded-lg bg-green-50 p-3 text-sm font-semibold text-green-800"><CircleCheck className="h-4 w-4" />No reconciliation issues were found.</div>}</SectionCard>
    <SectionCard title="Cash Received Evidence" description="View the authoritative bank transactions and manual composition behind cash received lines."><div className="space-y-3">{reconciliation.sourceLines.filter((line) => line.lineType !== "EXPENDITURE").map((line) => <details key={line.id} className="rounded-lg border border-brand-line p-4 dark:border-slate-700"><summary className="cursor-pointer list-none"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-bold">{line.categoryName}</p><Badge variant={line.sourceType === "BANK" ? "success" : line.sourceType === "MIXED" ? "warning" : "muted"}>{line.sourceType === "BANK" ? "Bank Statement" : line.sourceType === "MIXED" ? "Bank Statement + Manual Entry" : "Manual Entry"}</Badge></div><div className="text-right"><p className="text-xs font-bold uppercase text-slate-500">Report amount</p><p className="font-bold tabular-nums">{moneyLabel(line.actual, data.version.currency)}</p></div></div></summary><div className="mt-4 border-t border-brand-line pt-4 dark:border-slate-700"><div className="mb-3 grid gap-3 sm:grid-cols-2"><Field label="Bank Statement" value={moneyLabel(line.bankAmount, data.version.currency)} /><Field label="Manual Entry" value={moneyLabel(line.manualAmount, data.version.currency)} /></div>{line.evidence.length ? <div className="space-y-2">{line.evidence.map((evidence) => <div key={evidence.sourceId} className="rounded-md bg-slate-50 p-3 text-sm dark:bg-slate-800"><p className="font-medium">{evidence.originalDescription}</p><p className="mt-1 text-slate-600 dark:text-slate-300">{displayDate(evidence.transactionDate)} · {formatGrantLabel(evidence.direction)} · {moneyLabel(evidence.appliedAmount, data.version.currency)} · {evidence.statementFilename} · Page {evidence.sourcePage ?? "—"}, row {evidence.sourceRow ?? "—"}</p><p className="mt-1 text-xs text-slate-500">Transaction {evidence.transactionId} · Source {evidence.sourceId}</p></div>)}</div> : <p className="text-sm text-slate-500">This cash received line has no linked bank transactions and is recorded as a manual entry.</p>}</div></details>)}{!reconciliation.sourceLines.some((line) => line.lineType !== "EXPENDITURE") ? <p className="rounded-lg border border-dashed border-brand-line p-6 text-center text-sm text-slate-500">No cash received lines have been recorded.</p> : null}</div></SectionCard>
    <SectionCard title="Budget vs Actual" description="Authoritative report lines drive these totals; linked bank transactions are shown only as supporting evidence."><div className="space-y-3">{reconciliation.categories.map((category) => <details key={category.categoryName} className="group rounded-lg border border-brand-line p-4 dark:border-slate-700"><summary className="cursor-pointer list-none"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-[1.4fr_repeat(3,0.8fr)_auto]"><div><p className="font-bold">{category.categoryName}</p><div className="mt-1 flex flex-wrap gap-2"><Badge variant={category.sourceType === "BANK" ? "success" : category.sourceType === "MIXED" ? "warning" : "muted"}>{category.sourceType === "BANK" ? "Bank Statement" : category.sourceType === "MIXED" ? "Bank Statement + Manual Entry" : "Manual Entry"}</Badge><Badge variant={category.status === "OVER_BUDGET" ? "warning" : category.status === "WITHIN_BUDGET" ? "success" : "muted"}>{formatGrantLabel(category.status)}</Badge></div></div><Field label="Budget" value={category.budget === null ? "Not recorded" : moneyLabel(category.budget, data.version.currency)} /><Field label="Actual" value={moneyLabel(category.actual, data.version.currency)} /><Field label="Variance" value={category.variance === null ? "Not available" : moneyLabel(category.variance, data.version.currency)} /><span className="self-center text-sm font-bold text-brand-navy">{category.evidence.length ? "View Bank Evidence" : "View Breakdown"}</span></div></summary><div className="mt-4 border-t border-brand-line pt-4 dark:border-slate-700"><div className="mb-4 grid gap-3 sm:grid-cols-3"><Field label="Bank Statement" value={moneyLabel(category.bankAmount, data.version.currency)} /><Field label="Manual Entry" value={moneyLabel(category.manualAmount, data.version.currency)} /><Field label="Evidence Total" value={moneyLabel(category.evidenceTotal, data.version.currency)} /></div>{category.evidence.length ? <div className="space-y-3">{category.evidence.map((evidence) => <div key={evidence.sourceId} className="grid gap-2 rounded-md bg-slate-50 p-3 text-sm dark:bg-slate-800 sm:grid-cols-2 xl:grid-cols-4"><div className="sm:col-span-2"><p className="text-xs font-bold uppercase text-slate-500">Original bank description</p><p className="font-medium">{evidence.originalDescription}</p></div><Field label="Transaction date" value={displayDate(evidence.transactionDate)} /><Field label="Debit / Credit" value={formatGrantLabel(evidence.direction)} /><Field label="Transaction amount" value={moneyLabel(evidence.transactionAmount, data.version.currency)} /><Field label="Applied amount" value={moneyLabel(evidence.appliedAmount, data.version.currency)} /><Field label="Confirmed category" value={evidence.confirmedCategory} /><Field label="Running balance" value={evidence.runningBalance ? moneyLabel(evidence.runningBalance, data.version.currency) : "Not available"} /><div className="sm:col-span-2 xl:col-span-4"><p className="text-xs font-bold uppercase text-slate-500">Statement / Source</p><p>{evidence.statementFilename}{evidence.statementMonth ? ` · ${displayDate(evidence.statementMonth)}` : ""} · Page {evidence.sourcePage ?? "—"}, row {evidence.sourceRow ?? "—"}</p><p className="mt-1 text-xs text-slate-500">Transaction {evidence.transactionId} · Source {evidence.sourceId}</p></div></div>)}</div> : <p className="text-sm text-slate-500">This report line has no linked bank transactions and is recorded as a manual entry.</p>}</div></details>)}</div></SectionCard>
  </div>;
}

function SubmissionReadiness({ data, onNavigate }: { data: GrantReportEditorData; onNavigate: (section: DbeQuarterlyCashFlowSectionId) => void }) {
  if (data.version.historical) return <SectionCard title="Submission Readiness at Submission"><p className="text-sm text-slate-600 dark:text-slate-300">This is a previously submitted version. Its recorded readiness state, warning acknowledgement and any warning snapshot are shown in Submission History above. Current-version validation is not presented as the historical result.</p></SectionCard>;
  const readiness = data.quarterlyCashFlow.submissionReadiness;
  if (!readiness) return <SectionCard title="Submission Readiness"><p className="text-sm text-slate-500">Submission readiness is unavailable for this report.</p></SectionCard>;
  const groups: SubmissionCheckGroup[] = ["Report Information", "Financial Information", "Bank Evidence", "Supporting Documents", "Certification"];
  const submitted = Boolean(data.version.submittedAt);
  return <SectionCard title={submitted ? "Submission Status" : "Submission Readiness"} description={submitted ? "Read-only reconstruction from the saved report and linked evidence; submission-time facts are recorded in Submission History." : "Final validation of required report information, financial evidence and certification requirements before submission."}>
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-brand-line bg-slate-50 p-4 dark:border-slate-700 dark:bg-slate-800">
      <div><p className="text-xs font-bold uppercase text-slate-500">{submitted ? "Submission Status" : "Submission Readiness"}</p><p className="mt-1 text-sm">{submitted ? "This official version is submitted and locked. Historical warnings remain visible below." : readiness.attentionCount === 0 ? "All mandatory submission requirements pass." : `${readiness.attentionCount} item${readiness.attentionCount === 1 ? "" : "s"} require attention before this report can be submitted.`}</p></div>
      <Badge variant={submitted || readiness.state === "READY" ? "success" : "warning"} className={!submitted && readiness.state === "BLOCKED" ? "bg-red-50 text-red-800" : undefined}>{submitted ? "Submitted" : formatGrantLabel(readiness.state)}</Badge>
    </div>
    <div className="grid gap-4 xl:grid-cols-2">{groups.map((group) => {
      const checks = readiness.checks.filter((check) => check.group === group);
      return <div key={group} className="min-w-0 rounded-lg border border-brand-line p-4 dark:border-slate-700">
        <h3 className="font-bold">{group}</h3>
        <div className="mt-3 space-y-3">{checks.map((check) => <div key={check.id} className="rounded-md bg-slate-50 p-3 text-sm dark:bg-slate-800">
          <div className="flex flex-wrap items-start justify-between gap-2"><p className="font-semibold">{check.title}</p><Badge variant={check.status === "COMPLETE" ? "success" : check.status === "NOT_REQUIRED" ? "muted" : "warning"} className={check.status === "BLOCKED" ? "bg-red-50 text-red-800" : undefined}>{check.status === "BLOCKED" ? "Missing / Blocking" : check.status === "NEEDS_REVIEW" ? "Needs Review" : check.status === "NOT_REQUIRED" ? "Not Required" : "Complete"}</Badge></div>
          <p className="mt-1 text-slate-600 dark:text-slate-300">{grantReadinessPresentation(check, submitted).detail}</p>
          {grantReadinessPresentation(check, submitted).guidance ? <p className="mt-2 font-medium">{grantReadinessPresentation(check, submitted).guidance}</p> : null}
          {check.section ? <button type="button" className="mt-2 font-bold text-brand-navy underline underline-offset-2 focus-visible:outline focus-visible:outline-2 dark:text-blue-300" onClick={() => onNavigate(check.section!)}>Go to {dbeQuarterlyCashFlowSections.find((section) => section.id === check.section)?.label}</button> : null}
          {check.href ? <Link className="mt-2 inline-block font-bold text-brand-navy underline underline-offset-2 focus-visible:outline focus-visible:outline-2 dark:text-blue-300" href={check.href}>Open Bank Statements</Link> : null}
        </div>)}</div>
      </div>;
    })}</div>
    <p className="text-xs text-slate-500">{submitted ? "This submitted version remains available for audit and evidence review." : "This is a read-only assessment. Complete certification and final submission in Certification & Review."}</p>
  </SectionCard>;
}

function ReconciliationGroup({ title, rows, currency }: { title: string; rows: Array<[string, string | null]>; currency: string }) { return <div className="min-w-0 rounded-lg border border-brand-line p-4 dark:border-slate-700"><h3 className="font-bold">{title}</h3><dl className="mt-3 space-y-2 text-sm">{rows.map(([label, value]) => <Metric key={label} label={label} value={value === null ? "Not recorded" : formatGrantReconciliationCurrency(value, currency)} />)}</dl></div>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="grid grid-cols-[minmax(0,1fr)_max-content] items-start gap-x-4"><dt className="min-w-0 break-words text-slate-500">{label}</dt><dd className="whitespace-nowrap text-right font-bold tabular-nums">{value}</dd></div>; }

function CashFlowCertification({ data, rows, setRows, editable, onNavigate, onSubmitted }: { data: GrantReportEditorData; rows: CertificationDraft[]; setRows: React.Dispatch<React.SetStateAction<CertificationDraft[]>>; editable: boolean; onNavigate: (section: DbeQuarterlyCashFlowSectionId) => void; onSubmitted: (data: GrantReportEditorData) => void }) {
  return <SectionCard title="Certification & Review" description="Confirm the people responsible for preparing and approving this quarterly cash flow report.">
    <p className="rounded-lg bg-blue-50 p-3 text-sm text-brand-navy">ECDLink records who completed each explicit confirmation and when for audit purposes. Completing the names and dates alone does not certify the report.</p>
    {rows.map((row, index) => {
      const existing = data.certifications.find((item) => item.party === row.party);
      const label = row.party === "COMPILER" ? "Compiled By" : "Approved / Authorised By";
      return <div key={row.party} className="space-y-4 rounded-lg border border-brand-line p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">{label}</h3>{existing?.confirmedAt ? <span className="text-xs text-slate-500">Confirmed by {existing.confirmedBy} on {displayDate(existing.confirmedAt)}</span> : null}</div><div className="grid gap-3 md:grid-cols-3"><label className="text-sm font-bold">Name<input className={inputClass} value={row.nameSnapshot} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, nameSnapshot: event.target.value } : item))} /></label><label className="text-sm font-bold">Designation<input className={inputClass} value={row.designationSnapshot} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, designationSnapshot: event.target.value } : item))} /></label><label className="text-sm font-bold">Certification Date<input className={inputClass} type="date" value={row.certificationDate} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, certificationDate: event.target.value } : item))} /></label></div><label className="flex items-start gap-3 text-sm font-semibold"><input type="checkbox" className="mt-1 h-4 w-4" checked={row.digitallyConfirmed} disabled={!editable} onChange={(event) => setRows((current) => current.map((item, rowIndex) => rowIndex === index ? { ...item, digitallyConfirmed: event.target.checked } : item))} /><span>I confirm that the information in this grant report is accurate and complete to the best of my knowledge.</span></label></div>;
    })}
    <FinalSubmission data={data} onNavigate={onNavigate} onSubmitted={onSubmitted} />
  </SectionCard>;
}

function FinalSubmission({ data, onNavigate, onSubmitted }: { data: GrantReportEditorData; onNavigate: (section: DbeQuarterlyCashFlowSectionId) => void; onSubmitted: (data: GrantReportEditorData) => void }) {
  if (data.version.submittedAt) return <div data-final-submission className="space-y-3 border-t border-brand-line pt-5 dark:border-slate-700"><h3 className="text-lg font-bold">Final Submission</h3><p className="text-sm text-slate-600 dark:text-slate-300">This submitted version preserves the recorded certifications and submission details for audit and evidence review.</p><p className="rounded-lg border border-green-200 bg-green-50 p-3 text-sm font-semibold text-green-900">This report has been submitted and is read-only.</p></div>;
  const readiness = data.quarterlyCashFlow.submissionReadiness;
  const certificationsComplete = (["COMPILER", "APPROVER"] as const).every((party) => data.certifications.some((item) => item.party === party && item.digitallyConfirmed));
  const warnings = selectSubmissionAcknowledgementWarnings(readiness?.checks ?? []);
  const canSubmit = canShowQuarterlySubmissionAction({ editable: data.version.editable, readinessState: readiness?.state ?? null, certifications: data.certifications });

  return <div data-final-submission className="space-y-4 border-t border-brand-line pt-5 dark:border-slate-700">
    <div><h3 className="text-lg font-bold">Final Submission</h3><p className="mt-1 text-sm text-slate-600 dark:text-slate-300">Complete both certifications and review Submission Readiness before submitting this report.</p></div>
    {!certificationsComplete && data.version.editable ? <p className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm font-semibold text-amber-900">Save explicit compiler and approver certifications before submitting.</p> : null}
    {certificationsComplete && readiness?.state === "BLOCKED" ? <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-900"><p className="font-semibold">Submission is blocked by one or more readiness checks.</p><button type="button" className="mt-2 font-bold underline underline-offset-2 focus-visible:outline focus-visible:outline-2" onClick={() => onNavigate("submission_readiness")}>Review Submission Readiness</button></div> : null}
    {data.version.status === "SUBMITTED" ? <p className="rounded-lg border border-green-200 bg-green-50 p-3 text-sm font-semibold text-green-900">This report has been submitted and is read-only.</p> : null}
    {canSubmit ? <WorkflowActionDialog<{ acknowledgeWarnings: boolean }, { report: GrantReportEditorData }>
      title="Submit Quarterly Cash Flow Report?"
      description="This will finalise the current report version and prevent further editing. The server will recalculate submission readiness before it makes any change."
      trigger={{ label: "Submit Report" }}
      confirmationButton={{ label: "Submit Report", loadingLabel: "Submitting…", tone: "warning" }}
      initialValues={{ acknowledgeWarnings: false }}
      fields={readiness!.state === "NEEDS_REVIEW" ? [{ type: "checkbox", name: "acknowledgeWarnings", label: "I have reviewed the outstanding warnings and want to submit with these items recorded.", required: true }] : []}
      renderFields={() => warnings.length ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900"><p className="font-bold">Outstanding warnings</p><ul className="mt-2 list-disc space-y-1 pl-5">{warnings.map((warning) => <li key={warning.id}>{warning.title}: {warning.detail}</li>)}</ul></div> : <p className="text-sm text-slate-600">All mandatory checks currently pass. Submission will lock Version {data.version.versionNumber}.</p>}
      action={async (values): Promise<WorkflowActionResult<{ report: GrantReportEditorData }>> => {
        const response = await fetch(`/api/grant-reports/${data.report.id}/submit`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(values) });
        const body = await response.json();
        return response.ok ? { ok: true, data: body.data } : { ok: false, error: body.error ?? "The report could not be submitted." };
      }}
      successToast={{ title: "Report submitted", description: "The official report version is now locked and read-only." }}
      errorToast={{ title: "Submission failed", fallbackDescription: "The report could not be submitted." }}
      onSuccess={(result) => { if (result?.report) onSubmitted(result.report); }}
    /> : null}
  </div>;
}

function SectionCard({ title, description, children }: { title: string; description?: string; children: React.ReactNode }) { return <Card className="dark:border-slate-800 dark:bg-slate-900"><CardHeader><CardTitle className="dark:text-white">{title}</CardTitle>{description ? <p className="text-sm text-slate-500">{description}</p> : null}</CardHeader><CardContent className="space-y-5">{children}</CardContent></Card>; }
function Field({ label, value }: { label: string; value: string | null }) { return <div className="rounded-lg bg-slate-50 p-3 dark:bg-slate-800"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-sm font-semibold text-brand-ink dark:text-white">{value || "Not provided"}</p></div>; }
